PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS pods (id TEXT PRIMARY KEY, name TEXT NOT NULL, color_hex TEXT NOT NULL, anchor_date TEXT NOT NULL, cycle_offset INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, full_name TEXT NOT NULL, role_tag TEXT NOT NULL, pod_id TEXT REFERENCES pods(id), phone TEXT, status TEXT NOT NULL DEFAULT 'active', effective_from TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, calendar_token TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS worker_accounts (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, password_iterations INTEGER NOT NULL DEFAULT 100000, staff_id TEXT UNIQUE REFERENCES staff(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected')), must_change_password INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS worker_sessions (token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES worker_accounts(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_accounts (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, password_iterations INTEGER NOT NULL DEFAULT 100000, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES admin_accounts(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_login_limits (email TEXT NOT NULL, ip_hash TEXT NOT NULL, failures INTEGER NOT NULL DEFAULT 0, window_started_at TEXT NOT NULL, blocked_until TEXT, PRIMARY KEY(email,ip_hash));
CREATE TABLE IF NOT EXISTS worker_auth_limits (scope TEXT NOT NULL, email TEXT NOT NULL, ip_hash TEXT NOT NULL, failures INTEGER NOT NULL DEFAULT 0, window_started_at TEXT NOT NULL, blocked_until TEXT, PRIMARY KEY(scope,email,ip_hash));
CREATE TABLE IF NOT EXISTS staff_pod_assignments (month TEXT NOT NULL, staff_id TEXT NOT NULL REFERENCES staff(id), pod_id TEXT NOT NULL REFERENCES pods(id), row_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(month,staff_id));
CREATE TABLE IF NOT EXISTS shift_assignments (id TEXT PRIMARY KEY, shift_date TEXT NOT NULL, staff_id TEXT NOT NULL REFERENCES staff(id), shift_code TEXT NOT NULL CHECK(shift_code IN ('M','N','OFF','LEAVE')), is_override INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shift_date,staff_id));
CREATE TABLE IF NOT EXISTS shift_covers (id TEXT PRIMARY KEY, original_date TEXT NOT NULL, shift_code TEXT NOT NULL CHECK(shift_code IN ('M','N')), requester_id TEXT NOT NULL REFERENCES staff(id), cover_worker_id TEXT REFERENCES staff(id), payback_cover_id TEXT REFERENCES shift_covers(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','settled')), approved_by TEXT REFERENCES staff(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, return_date TEXT);
CREATE TABLE IF NOT EXISTS unavailability_flags (id TEXT PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff(id), start_date TEXT NOT NULL, end_date TEXT NOT NULL, reason TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS assignments_date_idx ON shift_assignments(shift_date);
CREATE INDEX IF NOT EXISTS covers_status_idx ON shift_covers(status);
CREATE INDEX IF NOT EXISTS availability_status_idx ON unavailability_flags(status);
CREATE INDEX IF NOT EXISTS worker_sessions_account_idx ON worker_sessions(account_id);
CREATE INDEX IF NOT EXISTS admin_sessions_account_idx ON admin_sessions(admin_id);
